-- T11 channel identities, verified account linking and durable WhatsApp delivery.
grant create on schema api,app_private to git_tutor_commands;
alter table app_private.conversations add column ownership_version integer not null default 1;
create table app_private.support_account_links(conversation_id uuid primary key references app_private.conversations(id),account_id uuid not null references app_private.accounts(id),learner_id uuid not null references app_private.learners(id),created_at timestamptz not null default now());
create table app_private.support_link_challenges(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references app_private.conversations(id),challenge_hash text unique not null,expires_at timestamptz not null,consumed_at timestamptz,created_at timestamptz not null default now());
create table app_private.whatsapp_channels(conversation_id uuid primary key references app_private.conversations(id),phone_number_id text not null,provider_mode text not null check(provider_mode in('fake','cloud')),wa_id text not null,consent text not null default 'service_only' check(consent in('service_only','opted_in','opted_out')),consent_observed_at timestamptz,unique(phone_number_id,provider_mode,wa_id));
create table app_private.whatsapp_templates(id uuid primary key default gen_random_uuid(),name text not null check(name~'^[a-z0-9_]{1,100}$'),language text not null check(language~'^[a-z]{2}(_[A-Z]{2})?$'),parameter_count integer not null check(parameter_count between 0 and 10),provider_mode text not null check(provider_mode in('fake','cloud')),approved boolean not null,approval_evidence text not null,created_by uuid references app_private.accounts(id),created_at timestamptz not null default now());
create table app_private.whatsapp_dispatch(message_id uuid primary key references app_private.support_messages(id),ownership_version integer not null,template_id uuid references app_private.whatsapp_templates(id),template_parameters jsonb not null default '[]',scenario text not null default 'success' check(scenario in('success','timeout_after_success','failure')));
create table app_private.whatsapp_events(id uuid primary key default gen_random_uuid(),phone_number_id text not null,provider_mode text not null,event_key text not null,event_hash text not null,event jsonb not null,created_at timestamptz not null default now(),unique(phone_number_id,provider_mode,event_key));
create table app_private.whatsapp_observations(id uuid primary key default gen_random_uuid(),message_id uuid not null references app_private.support_messages(id),source_identity text unique not null,outcome text not null,provider_message_id text,safe_error_code text,observed_at timestamptz not null default now());
create function app_private.support_ownership_generation()returns trigger language plpgsql set search_path='' as $$begin if(new.owner_account_id,new.state,new.bot_paused)is distinct from(old.owner_account_id,old.state,old.bot_paused)then new.ownership_version:=old.ownership_version+1;end if;return new;end$$;
create trigger support_ownership_generation before update on app_private.conversations for each row execute function app_private.support_ownership_generation();
create or replace function app_private.support_read_scope(p_actor uuid,p_conversation uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from app_private.conversations c where c.id=p_conversation and(app_private.support_staff(p_actor)or(c.account_id=p_actor and not exists(select 1 from app_private.support_account_links l where l.conversation_id=c.id and not(exists(select 1 from app_private.learners s where s.id=l.learner_id and s.account_id=p_actor)or exists(select 1 from app_private.guardian_links g where g.learner_id=l.learner_id and g.guardian_account_id=p_actor and g.revoked_at is null and g.valid_from<=now()and g.valid_until>now()and 'profile'=any(g.scopes)))))))$$;
alter function app_private.support_summary(uuid,uuid)rename to support_base_summary;
create function app_private.support_summary(p_actor uuid,p_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;c app_private.conversations%rowtype;begin result:=app_private.support_base_summary(p_actor,p_id);select * into c from app_private.conversations where id=p_id;return result||jsonb_build_object('can_handoff',coalesce(c.account_id=p_actor and c.state='bot',false),'can_link',coalesce(c.account_id=p_actor and not exists(select 1 from app_private.support_account_links where conversation_id=c.id),false),'can_escalate',coalesce(c.owner_account_id=p_actor and c.state='assigned'and app_private.support_staff(p_actor),false),'can_return',c.state='escalated'and app_private.has_role(p_actor,'admin'),'consent_status',(select consent from app_private.whatsapp_channels where conversation_id=c.id));end$$;
create function app_private.support_create_challenge(p_conversation uuid)returns text language plpgsql security definer set search_path='' as $$declare token text:=gen_random_uuid()::text||gen_random_uuid()::text;begin
 if exists(select 1 from app_private.support_account_links where conversation_id=p_conversation)then raise exception'STATE_CONFLICT';end if;
 update app_private.support_link_challenges set consumed_at=now()where conversation_id=p_conversation and consumed_at is null;
 insert into app_private.support_link_challenges(conversation_id,challenge_hash,expires_at)values(p_conversation,encode(extensions.digest(token,'sha256'),'hex'),now()+interval'15 minutes');return token;end$$;
create function api.issue_conversation_challenge(p_conversation_id uuid,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor(true);c app_private.conversations%rowtype;ctx jsonb;token text;begin
 select * into c from app_private.conversations where id=p_conversation_id for update;if c.account_id is distinct from actor or c.channel<>'website'then raise exception'FORBIDDEN';end if;
 ctx:=app_private.booking_begin(actor,'issue_conversation_challenge',jsonb_build_object('conversation_id',c.id),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 token:=app_private.support_create_challenge(c.id);return app_private.booking_finish(ctx,c.id,c.version,jsonb_build_object('conversation_id',c.id,'single_use_thread_challenge',token,'expires_at',now()+interval'15 minutes'),'support_link_challenge_created',jsonb_build_object('conversation_id',c.id));end$$;
create function api.link_conversation_account(p_conversation_id uuid,p_single_use_thread_challenge text,p_learner_id uuid,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();c app_private.conversations%rowtype;challenge app_private.support_link_challenges%rowtype;ctx jsonb;begin
 perform app_private.assert_learner_scope(actor,p_learner_id,'profile');select * into c from app_private.conversations where id=p_conversation_id for update;
 if c.id is null or p_single_use_thread_challenge is null or length(p_single_use_thread_challenge)<>72 then raise exception'FORBIDDEN';end if;
 ctx:=app_private.booking_begin(actor,'link_conversation_account',jsonb_build_object('conversation_id',c.id,'challenge_hash',encode(extensions.digest(p_single_use_thread_challenge,'sha256'),'hex'),'learner_id',p_learner_id),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 select * into challenge from app_private.support_link_challenges where conversation_id=c.id and challenge_hash=encode(extensions.digest(p_single_use_thread_challenge,'sha256'),'hex')for update;
 if challenge.id is null or challenge.consumed_at is not null or challenge.expires_at<=now()or exists(select 1 from app_private.support_account_links where conversation_id=c.id)then raise exception'FORBIDDEN';end if;
 update app_private.support_link_challenges set consumed_at=now()where id=challenge.id;insert into app_private.support_account_links values(c.id,actor,p_learner_id,now());update app_private.conversations set account_id=actor,version=version+1,updated_at=now()where id=c.id returning * into c;
 return app_private.booking_finish(ctx,c.id,c.version,jsonb_build_object('conversation_id',c.id,'state',c.state,'owner_id',null),'support_account_linked',jsonb_build_object('conversation_id',c.id,'learner_id',p_learner_id));end$$;
create function app_private.support_queue_whatsapp(p_conversation uuid,p_actor uuid,p_author text,p_text text,p_template uuid default null,p_parameters jsonb default '[]')returns uuid language plpgsql security definer set search_path='' as $$declare mid uuid;v integer;begin
 select ownership_version into v from app_private.conversations where id=p_conversation;mid:=app_private.support_add_message(p_conversation,p_actor,p_author,p_text,null,'queued');insert into app_private.whatsapp_dispatch(message_id,ownership_version,template_id,template_parameters)values(mid,v,p_template,p_parameters);perform app_private.enqueue_event(gen_random_uuid(),'support_whatsapp_dispatch',mid,jsonb_build_object('message_id',mid),'support.whatsapp_send');return mid;end$$;
alter function app_private.support_command(text,jsonb,text)rename to support_website_command;
create function app_private.support_command(p_name text,p_input jsonb,p_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor(true);c app_private.conversations%rowtype;channel app_private.whatsapp_channels%rowtype;t app_private.whatsapp_templates%rowtype;ctx jsonb;mid uuid;result jsonb;begin
 if p_name in('submit_message','request_handoff')and not app_private.support_read_scope(actor,(p_input->>'conversation_id')::uuid)then raise exception'FORBIDDEN';end if;
 if p_name<>'reply_to_conversation'or not exists(select 1 from app_private.conversations where id=(p_input->>'conversation_id')::uuid and channel='whatsapp')then result:=app_private.support_website_command(p_name,p_input,p_key);if p_name in('transfer_conversation','escalate_conversation')then perform app_private.enqueue_event(md5('support:'||(result->>'command_id'))::uuid,case when p_name='transfer_conversation'then'support_transferred'else'support_escalated'end,(result->>'conversation_id')::uuid,jsonb_build_object('conversation_id',result->>'conversation_id','version',result->'version'),'notifications.route');end if;return result;end if;
 perform app_private.require_actor();select * into c from app_private.conversations where id=(p_input->>'conversation_id')::uuid for update;if not app_private.support_staff(actor)or c.owner_account_id is distinct from actor then raise exception'OWNER_REQUIRED';end if;
 ctx:=app_private.booking_begin(actor,p_name,p_input,p_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 if c.version is distinct from(p_input->>'expected_version')::integer then raise exception'VERSION_CONFLICT';end if;if c.state<>'assigned'then raise exception'STATE_CONFLICT';end if;
 select * into channel from app_private.whatsapp_channels where conversation_id=c.id for update;if channel.consent='opted_out'then raise exception'CONSENT_REQUIRED';end if;
 if(p_input->>'text'is null)=(p_input->>'template_id'is null)then raise exception'VALIDATION_ERROR';end if;
 if p_input->>'template_id'is null then
  if c.last_whatsapp_user_message_at is null or c.last_whatsapp_user_message_at<=now()-interval'24 hours'then raise exception'WINDOW_CLOSED';end if;
  if length(btrim(p_input->>'text'))not between 1 and 4000 or p_input->'template_parameters'<>'[]'::jsonb then raise exception'VALIDATION_ERROR';end if;
 else
  select * into t from app_private.whatsapp_templates where id=(p_input->>'template_id')::uuid;
  if t.id is null or not t.approved or t.provider_mode<>channel.provider_mode then raise exception'TEMPLATE_REQUIRED';end if;
  if channel.consent<>'opted_in'then raise exception'CONSENT_REQUIRED';end if;
  if jsonb_typeof(p_input->'template_parameters')is distinct from'array'or jsonb_array_length(p_input->'template_parameters')<>t.parameter_count or exists(select 1 from jsonb_array_elements(p_input->'template_parameters')v where jsonb_typeof(v)<>'string'or length(v#>>'{}')not between 1 and 500)then raise exception'VALIDATION_ERROR';end if;
 end if;
 mid:=app_private.support_queue_whatsapp(c.id,actor,'staff',coalesce(btrim(p_input->>'text'),'Approved template: '||t.name),(p_input->>'template_id')::uuid,p_input->'template_parameters');update app_private.conversations set version=version+1,waiting_since=null,updated_at=now()where id=c.id returning * into c;
 return app_private.booking_finish(ctx,c.id,c.version,jsonb_build_object('conversation_id',c.id,'state',c.state,'owner_id',c.owner_account_id),'support_reply_queued',jsonb_build_object('conversation_id',c.id,'message_id',mid));end$$;
create function app_private.whatsapp_observe(p_message uuid,p_source text,p_outcome text,p_provider_id text,p_code text)returns jsonb language plpgsql security definer set search_path='' as $$declare d app_private.support_message_delivery%rowtype;nextstate text;begin
 if p_outcome not in('sent','delivered','read','failed','unknown')or(p_code is not null and p_code!~'^[A-Z0-9_]{1,80}$')then raise exception'VALIDATION_ERROR';end if;
 select * into d from app_private.support_message_delivery where message_id=p_message for update;if d.message_id is null then raise exception'NOT_FOUND';end if;
 if d.provider_message_id is not null and p_provider_id is not null and d.provider_message_id<>p_provider_id then raise exception'STATE_CONFLICT';end if;
 if exists(select 1 from app_private.whatsapp_observations where source_identity=p_source)then return jsonb_build_object('state',d.state);end if;
 insert into app_private.whatsapp_observations(message_id,source_identity,outcome,provider_message_id,safe_error_code)values(p_message,p_source,p_outcome,p_provider_id,p_code);
 nextstate:=case when d.state='read'or p_outcome='read'then'read'when d.state='delivered'or p_outcome='delivered'then'delivered'when d.state='suppressed'then'suppressed'when p_outcome='failed'then'failed'when d.state='sent'or p_outcome='sent'then'sent'else p_outcome end;
 update app_private.support_message_delivery set state=nextstate,provider_message_id=coalesce(provider_message_id,p_provider_id),safe_error_code=case when nextstate in('failed','unknown')then p_code end,updated_at=now()where message_id=p_message;return jsonb_build_object('state',nextstate);end$$;
create function app_private.record_whatsapp_event(p_phone text,p_mode text,p_event jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare key text;old app_private.whatsapp_events%rowtype;channel app_private.whatsapp_channels%rowtype;c app_private.conversations%rowtype;observed timestamptz:=(p_event->>'observed_at')::timestamptz;answer text;mid uuid;token text;begin
 if p_phone is null or length(p_phone)not between 1 and 100 or p_mode not in('fake','cloud')or(p_mode='fake'and not exists(select 1 from app_private.environment_metadata where environment in('test','development')and fixture_marker is not null))or p_event->>'kind'not in('message','status')or p_event->>'wa_id'!~'^\d{6,20}$'or p_event->>'event_hash'!~'^[a-f0-9]{64}$'or length(p_event->>'provider_message_id')not between 1 and 300 or observed is null or observed>now()+interval'5 minutes'then raise exception'VALIDATION_ERROR';end if;
 perform pg_advisory_xact_lock(hashtextextended('wa:'||p_mode||':'||p_phone||':'||(p_event->>'wa_id'),0));
 key:=(p_event->>'kind')||':'||(p_event->>'provider_message_id')||case when p_event->>'kind'='status'then':'||(p_event->>'status')||':'||(p_event->>'observed_at')else''end;
 select * into old from app_private.whatsapp_events where phone_number_id=p_phone and provider_mode=p_mode and event_key=key;if old.id is not null then if old.event_hash<>p_event->>'event_hash'then raise exception'IDEMPOTENCY_CONFLICT';end if;return jsonb_build_object('duplicate',true);end if;
 insert into app_private.whatsapp_events(phone_number_id,provider_mode,event_key,event_hash,event)values(p_phone,p_mode,key,p_event->>'event_hash',p_event);
 if p_event->>'kind'='status'then
  select m.id into mid from app_private.support_messages m join app_private.whatsapp_channels w on w.conversation_id=m.conversation_id join app_private.support_message_delivery d on d.message_id=m.id where w.phone_number_id=p_phone and w.provider_mode=p_mode and w.wa_id=p_event->>'wa_id'and(m.id=(p_event->>'message_id')::uuid or d.provider_message_id=p_event->>'provider_message_id');
  if mid is null then return jsonb_build_object('unmatched',true);end if;
  return app_private.whatsapp_observe(mid,'callback:'||p_phone||':'||key,p_event->>'status',p_event->>'provider_message_id',case when p_event->>'status'='failed'then'WHATSAPP_REJECTED'end);
 end if;
 if p_event->>'text'is null or length(p_event->>'text')not between 1 and 4000 then raise exception'VALIDATION_ERROR';end if;
 select * into channel from app_private.whatsapp_channels where phone_number_id=p_phone and provider_mode=p_mode and wa_id=p_event->>'wa_id';
 if channel.conversation_id is null then insert into app_private.conversations(channel,topic,source_token,source_confidence)values('whatsapp','WhatsApp inquiry',null,'provider_observed')returning * into c;insert into app_private.whatsapp_channels(conversation_id,phone_number_id,provider_mode,wa_id)values(c.id,p_phone,p_mode,p_event->>'wa_id')returning * into channel;else select * into c from app_private.conversations where id=channel.conversation_id for update;end if;
 perform app_private.support_add_message(c.id,null,'customer',p_event->>'text');
 if c.state='resolved'then c.state:='waiting';c.owner_account_id:=null;c.bot_paused:=true;c.waiting_since:=now();end if;
 if lower(btrim(p_event->>'text'))in('stop','unsubscribe','opt out','start','yes','subscribe')and(channel.consent_observed_at is null or observed>=channel.consent_observed_at)then update app_private.whatsapp_channels set consent=case when lower(btrim(p_event->>'text'))in('stop','unsubscribe','opt out')then'opted_out'else'opted_in'end,consent_observed_at=observed where conversation_id=c.id returning * into channel;end if;
 c.last_whatsapp_user_message_at:=greatest(c.last_whatsapp_user_message_at,observed);c.last_incoming_at:=greatest(c.last_incoming_at,observed);
 if channel.consent='opted_out'then if c.state='bot'then c.state:='waiting';end if;c.bot_paused:=true;c.waiting_since:=coalesce(c.waiting_since,now());
 elsif lower(btrim(p_event->>'text'))='link'and not exists(select 1 from app_private.support_account_links where conversation_id=c.id)then token:=app_private.support_create_challenge(c.id);answer:='Sign in at the Git Tutor website and open Support. Link conversation '||c.id||' using this single-use code (expires in 15 minutes): '||token;
 elsif c.state='bot'and not c.bot_paused then
  if p_event->>'text'!~*'(refund|dispute|complain|human|person|account|password|personal|tutor fee|compensation|bank|مبلغ|استرداد|موظف)'then select f.answer into answer from app_private.approved_faq_answers f where f.active and p_event->>'text'~*f.question_pattern order by f.id limit 1;end if;
  if answer is null then c.state:='waiting';c.bot_paused:=true;c.waiting_since:=now();answer:='Your request is waiting for a person. FAQ automation is paused. Staffed hours are not yet configured; the team will respond when available.';end if;
 end if;
 update app_private.conversations set state=c.state,owner_account_id=c.owner_account_id,bot_paused=c.bot_paused,waiting_since=c.waiting_since,last_whatsapp_user_message_at=c.last_whatsapp_user_message_at,last_incoming_at=c.last_incoming_at,version=version+1,updated_at=now()where id=c.id;
 if answer is not null then perform app_private.support_queue_whatsapp(c.id,null,case when c.state='bot'and token is null then'bot'else'system'end,answer);end if;
 return jsonb_build_object('conversation_id',c.id,'duplicate',false);end$$;
create function app_private.whatsapp_assert_job(p_message uuid,p_job uuid,p_lease uuid)returns void language plpgsql security definer set search_path='' as $$begin if not exists(select 1 from app_private.outbox_jobs j join app_private.domain_events e on e.id=j.event_id where j.id=p_job and j.purpose='support.whatsapp_send'and j.state='leased'and j.lease_token=p_lease and j.lease_expires_at>clock_timestamp()and e.event_type='support_whatsapp_dispatch'and e.aggregate_id=p_message and e.payload=jsonb_build_object('message_id',p_message))then raise exception'LEASE_LOST';end if;end$$;
create function app_private.prepare_whatsapp_send(p_message uuid,p_job uuid,p_lease uuid,p_mode text)returns jsonb language plpgsql security definer set search_path='' as $$declare c app_private.conversations%rowtype;w app_private.whatsapp_channels%rowtype;m app_private.support_messages%rowtype;d app_private.support_message_delivery%rowtype;q app_private.whatsapp_dispatch%rowtype;t app_private.whatsapp_templates%rowtype;code text;begin
 perform app_private.whatsapp_assert_job(p_message,p_job,p_lease);select * into m from app_private.support_messages where id=p_message;select * into c from app_private.conversations where id=m.conversation_id for update;select * into w from app_private.whatsapp_channels where conversation_id=c.id for update;select * into d from app_private.support_message_delivery where message_id=m.id for update;select * into q from app_private.whatsapp_dispatch where message_id=m.id;
 if q.message_id is null or p_mode not in('fake','cloud')then raise exception'NOT_FOUND';end if;if q.template_id is not null then select * into t from app_private.whatsapp_templates where id=q.template_id;end if;
 if d.state in('sent','delivered','read','failed','suppressed')then return jsonb_build_object('state','complete','message_id',m.id);end if;
 if w.provider_mode<>p_mode then code:='PROVIDER_MODE_MISMATCH';elsif w.consent='opted_out'then code:='CONSENT_REQUIRED';elsif c.ownership_version<>q.ownership_version or(m.author='bot'and(c.bot_paused or c.state<>'bot'))or(m.author='staff'and(c.owner_account_id is distinct from m.actor_account_id or c.state<>'assigned'or not app_private.support_staff(m.actor_account_id)))then code:='CURRENT_OWNER_REQUIRED';
 elsif q.template_id is null and(c.last_whatsapp_user_message_at is null or c.last_whatsapp_user_message_at<=clock_timestamp()-interval'24 hours')then code:='WINDOW_CLOSED';
 elsif q.template_id is not null then select * into t from app_private.whatsapp_templates where id=q.template_id;if t.id is null or not t.approved or t.provider_mode<>p_mode then code:='TEMPLATE_REQUIRED';elsif w.consent<>'opted_in'then code:='CONSENT_REQUIRED';end if;end if;
 if code is not null and d.state<>'unknown'then update app_private.support_message_delivery set state='suppressed',safe_error_code=code,updated_at=now()where message_id=m.id;return jsonb_build_object('state','complete','message_id',m.id);end if;
 return jsonb_build_object('state','ready','message_id',m.id,'attempt_state',d.state,'destination',w.wa_id,'text',case when q.template_id is null then m.text end,'template',case when q.template_id is not null then jsonb_build_object('name',t.name,'language',t.language,'parameters',q.template_parameters)end,'scenario',case when p_mode='fake'then q.scenario else'success'end);end$$;
create function app_private.finalize_whatsapp_send(p_message uuid,p_job uuid,p_lease uuid,p_observation jsonb)returns jsonb language plpgsql security definer set search_path='' as $$begin perform app_private.whatsapp_assert_job(p_message,p_job,p_lease);return app_private.whatsapp_observe(p_message,'job:'||p_job||':'||p_lease,p_observation->>'outcome',p_observation->>'provider_message_id',p_observation->>'safe_error_code');end$$;
create function api.reconcile_whatsapp_message(p_conversation_id uuid,p_message_id uuid,p_expected_version integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();c app_private.conversations%rowtype;ctx jsonb;state text;begin
 select * into c from app_private.conversations where id=p_conversation_id for update;if not app_private.support_staff(actor)or(c.owner_account_id is distinct from actor and not app_private.has_role(actor,'admin'))then raise exception'FORBIDDEN';end if;
 ctx:=app_private.booking_begin(actor,'reconcile_whatsapp_message',jsonb_build_object('conversation_id',c.id,'message_id',p_message_id,'expected_version',p_expected_version),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 if c.version<>p_expected_version then raise exception'VERSION_CONFLICT';end if;
 select d.state into state from app_private.support_message_delivery d join app_private.support_messages m on m.id=d.message_id where m.id=p_message_id and m.conversation_id=c.id and exists(select 1 from app_private.whatsapp_dispatch where message_id=m.id)for update of d;if state is distinct from'unknown'and not(state='queued'and exists(select 1 from app_private.outbox_jobs j join app_private.domain_events e on e.id=j.event_id where e.aggregate_id=p_message_id and j.purpose='support.whatsapp_send'and(j.state='reconciliation'or(j.state='leased'and j.lease_expires_at<=clock_timestamp()))))then raise exception'STATE_CONFLICT';end if;
 update app_private.support_message_delivery set state='unknown',safe_error_code='WHATSAPP_RECONCILIATION_REQUIRED'where message_id=p_message_id;
 perform app_private.enqueue_event(gen_random_uuid(),'support_whatsapp_dispatch',p_message_id,jsonb_build_object('message_id',p_message_id),'support.whatsapp_send');
 return app_private.booking_finish(ctx,c.id,c.version,jsonb_build_object('conversation_id',c.id,'state',c.state,'owner_id',c.owner_account_id),'support_reconciliation_requested',jsonb_build_object('message_id',p_message_id));end$$;
create function api.withdraw_whatsapp_consent(p_conversation_id uuid,p_expected_version integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();c app_private.conversations%rowtype;ctx jsonb;begin select * into c from app_private.conversations where id=p_conversation_id for update;if not app_private.support_read_scope(actor,c.id)or not(c.account_id=actor or c.owner_account_id=actor or app_private.has_role(actor,'admin'))then raise exception'FORBIDDEN';end if;
 ctx:=app_private.booking_begin(actor,'withdraw_whatsapp_consent',jsonb_build_object('conversation_id',c.id,'expected_version',p_expected_version),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;if c.version<>p_expected_version then raise exception'VERSION_CONFLICT';end if;
 update app_private.whatsapp_channels set consent='opted_out',consent_observed_at=now()where conversation_id=c.id;if not found then raise exception'STATE_CONFLICT';end if;update app_private.conversations set version=version+1,updated_at=now()where id=c.id returning * into c;
 return app_private.booking_finish(ctx,c.id,c.version,jsonb_build_object('conversation_id',c.id,'state',c.state,'owner_id',case when app_private.support_staff(actor)then c.owner_account_id end),'support_consent_withdrawn',jsonb_build_object('conversation_id',c.id));end$$;
create function api.register_whatsapp_template(p_name text,p_language text,p_parameter_count integer,p_provider_mode text,p_approval_evidence text,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();ctx jsonb;tid uuid;begin perform app_private.require_role(actor,'admin');if p_name!~'^[a-z0-9_]{1,100}$'or p_language!~'^[a-z]{2}(_[A-Z]{2})?$'or p_parameter_count not between 0 and 10 or p_provider_mode not in('fake','cloud')or length(btrim(p_approval_evidence))not between 10 and 2000 then raise exception'VALIDATION_ERROR';end if;
 ctx:=app_private.booking_begin(actor,'register_whatsapp_template',jsonb_build_object('name',p_name,'language',p_language,'parameter_count',p_parameter_count,'provider_mode',p_provider_mode,'approval_evidence',p_approval_evidence),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 insert into app_private.whatsapp_templates(name,language,parameter_count,provider_mode,approved,approval_evidence,created_by)values(p_name,p_language,p_parameter_count,p_provider_mode,true,p_approval_evidence,actor)returning id into tid;return app_private.booking_finish(ctx,tid,1,jsonb_build_object('template_id',tid),'whatsapp_template_registered',jsonb_build_object('template_id',tid));end$$;
create function api.get_support_options()returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();begin if not app_private.support_staff(actor)then raise exception'FORBIDDEN';end if;return jsonb_build_object('is_admin',app_private.has_role(actor,'admin'),'staff',(select coalesce(jsonb_agg(jsonb_build_object('account_id',a.id,'label',p.display_name)order by p.display_name),'[]')from app_private.accounts a join app_private.people p on p.id=a.person_id where app_private.support_staff(a.id)),'templates',(select coalesce(jsonb_agg(jsonb_build_object('template_id',id,'name',name,'language',language,'parameter_count',parameter_count,'provider_mode',provider_mode)order by created_at desc),'[]')from app_private.whatsapp_templates where approved));end$$;
-- Current relationship checks apply before projection, including paged customer history.
create or replace function app_private.support_list(p_staff boolean,p_state text,p_channel text,p_owner_id uuid,p_cursor uuid,p_limit integer)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor(true);items jsonb;begin
 if p_staff and not app_private.support_staff(actor)then raise exception'FORBIDDEN';end if;if p_limit is null or p_limit not between 1 and 100 or(p_state is not null and p_state not in('bot','waiting','assigned','escalated','resolved'))or(p_channel is not null and p_channel not in('website','whatsapp'))or(not p_staff and p_owner_id is not null)then raise exception'VALIDATION_ERROR';end if;
 if p_cursor is not null and not exists(select 1 from app_private.conversations where id=p_cursor and(p_staff or(account_id=actor and app_private.support_read_scope(actor,id))))then raise exception'NOT_FOUND';end if;
 select coalesce(jsonb_agg(x.item order by x.created_at desc,x.id desc),'[]'::jsonb)into items from(select c.id,c.created_at,app_private.support_summary(actor,c.id)item from app_private.conversations c where(p_staff or(c.account_id=actor and app_private.support_read_scope(actor,c.id)))and(p_state is null or c.state=p_state)and(p_channel is null or c.channel=p_channel)and(p_owner_id is null or c.owner_account_id=p_owner_id)and(p_cursor is null or(c.created_at,c.id)<(select created_at,id from app_private.conversations where id=p_cursor))order by c.created_at desc,c.id desc limit p_limit)x;return jsonb_build_object('items',items,'next_cursor',case when jsonb_array_length(items)=p_limit then items->-1->>'conversation_id'else null end);end$$;
do $$declare t record;f record;begin
 for t in select tablename from pg_tables where schemaname='app_private'and tablename in('support_account_links','support_link_challenges','whatsapp_channels','whatsapp_templates','whatsapp_dispatch','whatsapp_events','whatsapp_observations')loop
 execute format('alter table app_private.%I enable row level security',t.tablename);execute format('create policy commands_access on app_private.%I to git_tutor_commands using(true)with check(true)',t.tablename);execute format('revoke all on app_private.%I from public,anon,authenticated,service_role,git_tutor_worker',t.tablename);execute format('grant select,insert on app_private.%I to git_tutor_commands',t.tablename);
 if t.tablename in('support_link_challenges','whatsapp_channels')then execute format('grant update on app_private.%I to git_tutor_commands',t.tablename);else execute format('create trigger immutable_row before update or delete on app_private.%I for each row execute function app_private.reject_immutable_change()',t.tablename);end if;end loop;
 for f in select p.oid::regprocedure::text signature,n.nspname,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('api','app_private')and(p.proname like'whatsapp_%'or p.proname like'support_%'or p.proname=any(array['issue_conversation_challenge','link_conversation_account','record_whatsapp_event','prepare_whatsapp_send','finalize_whatsapp_send','reconcile_whatsapp_message','withdraw_whatsapp_consent','register_whatsapp_template','get_support_options']))loop
 execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api'then execute format('grant execute on function %s to authenticated',f.signature);elsif f.proname in('record_whatsapp_event','prepare_whatsapp_send','finalize_whatsapp_send')then execute format('grant execute on function %s to git_tutor_worker',f.signature);end if;end loop;end$$;
revoke create on schema api,app_private from git_tutor_commands;
